{
  "title": "The Broken Banner Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The party gathers at the ruined city gates.",
      "visual_description": "Massive iron gates, half-crumbled, with faded royal crests. Dust motes hang in the evening light.",
      "characters": ["Map Reader", "Scout", "Magic Helper"]
    },
    {
      "scene_number": 2,
      "caption": "The scout checks for patrols near the outer wall.",
      "visual_description": "Scout peering around a broken tower, armored patrol clanking in the distance beyond rubble.",
      "characters": ["Scout", "Armored Patrol"]
    },
    {
      "scene_number": 3,
      "caption": "Frightened townspeople flee through a market square.",
      "visual_description": "Crowd of pale-faced civilians clutching bundles, knocking over rotten fruit stalls.",
      "characters": ["Frightened Townspeople"]
    },
    {
      "scene_number": 4,
      "caption": "The magic helper examines a cursed tower door.",
      "visual_description": "Twisted black stone archway, runes pulsing with sickly green light, the magic helper's hand glowing in response.",
      "characters": ["Magic Helper", "Map Reader"]
    },
    {
      "scene_number": 5,
      "caption": "Inside the tower, illusions of treasure lure the party.",
      "visual_description": "Golden coins and gems floating in midair, shifting to reveal skeletons beneath.",
      "characters": ["Map Reader", "Scout", "Magic Helper"]
    },
    {
      "scene_number": 6,
      "caption": "Rumors of a dragon echo from a tavern ruin.",
      "visual_description": "Collapsed inn with a sign reading 'Dragon's Rest', locals whispering in the shadows.",
      "characters": ["Frightened Townspeople", "Scout"]
    },
    {
      "scene_number": 7,
      "caption": "The party finds an old royal banner in a forgotten hall.",
      "visual_description": "Tattered crimson and gold banner hanging from a cracked ceiling, dust-covered throne below.",
      "characters": ["Map Reader", "Magic Helper"]
    },
    {
      "scene_number": 8,
      "caption": "A magic door blocks the path to the keep.",
      "visual_description": "Ornate door of silver and obsidian, glowing symbols shifting like living things.",
      "characters": ["Magic Helper", "Map Reader", "Scout"]
    },
    {
      "scene_number": 9,
      "caption": "The scout disables a trap triggered by the door's riddle.",
      "visual_description": "Crossbow bolts firing from wall slits, scout rolling aside as bolts shatter stone.",
      "characters": ["Scout", "Magic Helper"]
    },
    {
      "scene_number": 10,
      "caption": "Inside the keep, the rescue target is found in a cage.",
      "visual_description": "Iron cage suspended from chains, a figure slumped inside, torchlight flickering on wet stone.",
      "characters": ["Map Reader", "Scout", "Magic Helper", "Rescue Target"]
    },
    {
      "scene_number": 11,
      "caption": "The magic helper shatters the cage lock with a spell.",
      "visual_description": "Blue-white energy arcs from the magic helper's hand, lock glows red then explodes.",
      "characters": ["Magic Helper", "Rescue Target", "Map Reader"]
    },
    {
      "scene_number": 12,
      "caption": "Patrols converge on the keep entrance.",
      "visual_description": "Armored guards with torches forming a phalanx, shouting orders.",
      "characters": ["Armored Patrol", "Scout"]
    },
    {
      "scene_number": 13,
      "caption": "The party escapes through a crumbling treasury.",
      "visual_description": "Collapsed pillars and scattered gold coins, a narrow passage behind a fallen statue.",
      "characters": ["Map Reader", "Scout", "Magic Helper", "Rescue Target"]
    },
    {
      "scene_number": 14,
      "caption": "A false dragon roar echoes in a courtyard.",
      "visual_description": "Giant puppet wings and a mechanical head operated by hidden townspeople, casting huge shadows.",
      "characters": ["Frightened Townspeople", "Scout", "Rescue Target"]
    },
    {
      "scene_number": 15,
      "caption": "The magic door chases them with shifting walls.",
      "visual_description": "Corridor walls sliding and rotating, the silver door appearing at each turn.",
      "characters": ["Magic Helper", "Map Reader", "Scout", "Rescue Target"]
    },
    {
      "scene_number": 16,
      "caption": "They reach the final bridge under arrow fire.",
      "visual_description": "Rope bridge spanning a chasm, arrows whizzing past, patrols at the far end.",
      "characters": ["Armored Patrol", "Scout", "Magic Helper", "Map Reader", "Rescue Target"]
    },
    {
      "scene_number": 17,
      "caption": "The magic helper collapses the bridge behind them.",
      "visual_description": "Ropes snapping in a burst of flame, the bridge falling into mist below.",
      "characters": ["Magic Helper", "Scout", "Map Reader", "Rescue Target"]
    },
    {
      "scene_number": 18,
      "caption": "The party emerges on the distant cliff, safe at last.",
      "visual_description": "Sunrise over green hills, ruined city in the distance, the group breathing heavily.",
      "characters": ["Map Reader", "Scout", "Magic Helper", "Rescue Target"]
    }
  ]
}

